WITH cleaned AS (SELECT id, supplier_name, city, rating, REGEXP_REPLACE(supplier_name, ' ', '_') AS supplier_name_slug FROM suppliers WHERE city IS DISTINCT FROM 'Bangkok' AND city IS NOT NULL), not_flagged AS (SELECT s.* FROM cleaned s WHERE NOT EXISTS (SELECT 1 FROM products ch WHERE ch.supplier_id = s.id AND ch.supplier_id IS NOT NULL)), eligible AS (SELECT s.* FROM not_flagged s WHERE NOT EXISTS (SELECT 1 FROM products ch WHERE ch.supplier_id = s.id AND ch.brand = 'Umbrella')), scored AS (SELECT *, ROW_NUMBER() OVER (ORDER BY rating DESC, id) AS row_seq, DENSE_RANK() OVER (PARTITION BY city ORDER BY rating NULLS LAST) AS rating_dense_rank, NTILE(3) OVER (PARTITION BY city ORDER BY rating DESC, id) AS rating_bucket FROM eligible), with_latest AS (SELECT s.id, s.rating, s.supplier_name_slug, s.row_seq, s.rating_dense_rank, s.rating_bucket, latest.price, latest.stock_qty FROM scored s LEFT JOIN LATERAL (SELECT c.price, c.stock_qty FROM products c WHERE c.supplier_id = s.id ORDER BY c.cost DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT id, rating, supplier_name_slug, row_seq, rating_dense_rank, price, stock_qty FROM with_latest;
